function mergeSeoPageEnhancements(key, page) {
  const primary = ARABIC_SEO_2026_ENHANCEMENTS[key] || {};
  const cluster = ARABIC_SEO_2026_CLUSTER_ENHANCEMENTS[key] || {};
  const deepening = ARABIC_SEO_2026_DEEPENING[key] || {};
  const finalDepth = ARABIC_SEO_2026_FINAL_DEPTH[key] || {};
  const pillarExtraDepth = ARABIC_SEO_2026_PILLAR_EXTRA_DEPTH[key] || {};

  return {
    ...page,
    ...primary,
    ...cluster,
    ...deepening,
    ...finalDepth,
    ...pillarExtraDepth,
    author: MAWSOUQ_EDITORIAL_AUTHOR,
    secondaryKeywords: Array.from(
      new Set([
        ...(page.secondaryKeywords || []),
        ...(primary.secondaryKeywords || []),
        ...(cluster.secondaryKeywords || []),
        ...(deepening.secondaryKeywords || []),
        ...(finalDepth.secondaryKeywords || []),
        ...(pillarExtraDepth.secondaryKeywords || []),
      ]),
    ),
    clusterLinks:
      pillarExtraDepth.clusterLinks ||
      finalDepth.clusterLinks ||
      deepening.clusterLinks ||
      cluster.clusterLinks ||
      primary.clusterLinks ||
      page.clusterLinks ||
      [],
    sourceLinks:
      pillarExtraDepth.sourceLinks ||
      finalDepth.sourceLinks ||
      deepening.sourceLinks ||
      cluster.sourceLinks ||
      primary.sourceLinks ||
      page.sourceLinks ||
      [],
    sections: [
      ...(page.sections || []),
      ...(primary.extraSections || []),
      ...(cluster.extraSections || []),
      ...(deepening.extraSections || []),
      ...(finalDepth.extraSections || []),
      ...(pillarExtraDepth.extraSections || []),
    ],
    faqs: [
      ...(page.faqs || []),
      ...(primary.extraFaqs || []),
      ...(cluster.extraFaqs || []),
      ...(deepening.extraFaqs || []),
      ...(finalDepth.extraFaqs || []),
      ...(pillarExtraDepth.extraFaqs || []),
    ],
  };
}

export const ARABIC_SEO_2026_PAGES = Object.fromEntries(
  Object.entries(ARABIC_SEO_2026_BASE_PAGES).map(([key, page]) => [
    key,
    mergeSeoPageEnhancements(key, page),
  ]),
);

export function getArabicSeo2026Page(key) {
  const page = ARABIC_SEO_2026_PAGES[key];
  if (!page) throw new Error(`Unknown Arabic SEO 2026 page key: ${key}`);
  return page;
}

export function getArabicSeo2026Metadata(key) {
  const page = getArabicSeo2026Page(key);
  const canonical = `${SITE_URL}/${page.slug}/`;
  const image = `${SITE_URL}${page.heroImage}`;

  return {
    title: page.metaTitle,
    description: page.metaDescription,
    authors: [
      {
        name: page.author?.name || "فريق موسوق",
        url: `${SITE_URL}${page.author?.url || "/عن-الشركة/"}`,
      },
    ],
    creator: page.author?.name || "فريق موسوق",
    publisher: "Mawsooq",
    keywords: [page.primaryKeyword, ...(page.secondaryKeywords || []), page.title, page.category, "موسوق", "Mawsooq", "السعودية"],
    alternates: { canonical },
    robots: {
      index: true,
      follow: true,
      googleBot: {
        index: true,
        follow: true,
        "max-image-preview": "large",
        "max-snippet": -1,
        "max-video-preview": -1,
      },
    },
    openGraph: {
      type: "article",
      locale: "ar_SA",
      siteName: "موسوق",
      url: canonical,
      title: page.metaTitle,
      description: page.metaDescription,
      authors: [page.author?.name || "فريق موسوق"],
      images: [{ url: image, width: 1600, height: 900, alt: page.imageAlt }],
    },
    twitter: {
      card: "summary_large_image",
      title: page.metaTitle,
      description: page.metaDescription,
      images: [image],
    },
  };
}

export function getAllArabicSeo2026Entries() {
  return Object.values(ARABIC_SEO_2026_PAGES).map((page) => ({
    url: `${SITE_URL}/${page.slug}/`,
    lastModified: page.dateModified,
    changeFrequency: page.pageType === "pillar" || page.pageType === "local-commercial" ? "weekly" : "monthly",
    priority: page.pageType === "pillar" || page.pageType === "local-commercial" ? 0.95 : 0.86,
  }));
}

export function getArabicSeo2026BlogCards() {
  return Object.values(ARABIC_SEO_2026_PAGES).map((page) => ({
    slug: page.slug,
    title: page.title,
    excerpt: page.subtitle,
    category:
      page.category.includes("تكلفة") || page.slug.includes("تكلفة") || page.slug.includes("سعر")
        ? "تكاليف البناء"
        : "التصميم المعماري",
    image: page.heroImage,
  }));
}

export { DATA_AS_OF };
